import 'package:collection/collection.dart';

void demo(List<Order> orders, String id) {
  // ❌ throws "Bad state: No element" the first time nothing matches
  final pending = orders.firstWhere((o) => o.status == 'pending');

  // ✅ a default, when one honestly exists
  final safe = orders.firstWhere(
    (o) => o.status == 'pending',
    orElse: () => Order.none,
  );

  // ✅ the usual answer — absence becomes null, not an exception
  final hit = orders.firstWhereOrNull((o) => o.status == 'pending');
  if (hit != null) ship(hit);

  // a pattern binds and narrows in one step
  if (orders.firstWhereOrNull((o) => o.id == id) case final o?) ship(o);

  // singleWhere throws on BOTH sides
  [1, 2].singleWhere((e) => e > 5);   // Bad state: No element
  [6, 7].singleWhere((e) => e > 5);   // Bad state: Too many elements

  // same library, different convention: a sentinel, not a throw
  final i = orders.indexWhere((o) => o.id == id);
  if (i != -1) orders.removeAt(i);

  // fold has a seed and survives an empty list; reduce does not
  final total = orders.fold<int>(0, (sum, o) => sum + o.cents);
  print('$total ${safe.id} ${pending.id}');
}

import 'package:flutter/foundation.dart';

class Money {
  final int cents;
  final String currency;
  const Money(this.cents, this.currency);

  @override
  bool operator ==(Object other) =>
      other is Money && other.cents == cents && other.currency == currency;

  // ❌ with == alone the Set hashes first, lands in two buckets
  //    and never calls == at all
  // ✅ hash the same fields == compares
  @override
  int get hashCode => Object.hash(cents, currency);
}

class Tag {
  String name;              // ❌ mutable and part of ==
  Tag(this.name);
  @override
  bool operator ==(Object other) => other is Tag && other.name == name;
  @override
  int get hashCode => name.hashCode;
}

void main() {
  print({const Money(1, 'usd'), const Money(1, 'usd')}.length); // 1

  final tags = {Tag('draft')};
  tags.first.name = 'final';        // hash changed, bucket did not
  print(tags.contains(Tag('final'))); // false — and it can never be removed

  // records bring structural equality for free: composite keys, no boilerplate
  final perDay = <(int, String), int>{};
  perDay[(7, '2026-09-08')] = 3;
  print(perDay[(7, '2026-09-08')]);   // 3

  // == is what lets a notifier skip work
  final n = ValueNotifier(const Money(1, 'usd'));
  n.value = const Money(1, 'usd');    // equal: no listener is fired
}

import 'dart:convert';

void parse(String body) {
  final decoded = jsonDecode(body);      // static type dynamic
  print(decoded.runtimeType);            // List<dynamic>

  // ❌ elements are fine; the list's own type argument is not
  // final rows = decoded as List<Map<String, dynamic>>;
  // TypeError: type 'List<dynamic>' is not a subtype of
  //            type 'List<Map<String, dynamic>>' in type cast

  // ⚠️ lazy checked view — no copy, but a bad element throws on read,
  //    far away from here
  final view = (decoded as List).cast<Map<String, dynamic>>();

  // ⚠️ eager copy — throws here, allocates a second list
  final copy = List<Map<String, dynamic>>.from(decoded as List);

  // ✅ cast one element at a time, right next to the parse
  final users = (decoded as List)
      .map((e) => User.fromJson(e as Map<String, dynamic>))
      .toList();

  print('${view.length} ${copy.length} ${users.length}');
}

