  print(<int>[1, 2] is List<num>);                // true — covariant
}

class Animal {}
class Dog extends Animal {}

extension AnimalX on Animal {
  String speak() => 'animal';
}
extension DogX on Dog {
  String speak() => 'woof';        // more specific on-type wins for a Dog
}

extension NullableX on String? {
  bool get isBlank => this?.trim().isEmpty ?? true;
}

class Cat {
  String speak() => 'meow';        // a real member
}
extension CatX on Cat {
  String speak() => 'never runs';  // instance member always wins
}

void main() {
  final Animal a = Dog();
  print(a.speak());                // "animal" — static type decides
  print(Dog().speak());            // "woof"

  final dynamic d = Dog();
  // d.speak();                    // ❌ NoSuchMethodError at run time:
                                   //    dynamic has no static type to match

  print(Cat().speak());            // "meow" — CatX is dead code

  print(null.isBlank);             // true — extensions may accept null

  // when two unrelated extensions collide, apply one explicitly
  print(AnimalX(Dog()).speak());   // "animal"
}

