class NativeBuffer {
  // static: if the Finalizer is collected, it stops firing entirely
  static final Finalizer<int> _finalizer =
      Finalizer((size) => print('leaked $size bytes — someone skipped free()'));

  final int size;
  bool _freed = false;

  NativeBuffer(this.size) {
    // ❌ the token references the object, so it can never become unreachable
    // _finalizer.attach(this, this);

    // ✅ token is plain data; the object is only the detach key
    _finalizer.attach(this, size, detach: this);
  }

  // the real cleanup path stays explicit
  void free() {
    if (_freed) return;
    _freed = true;
    _finalizer.detach(this);
    // ... release the native allocation here
  }
}
